// Command csvstat profiles the columns of a CSV file.
package main

import (
	"os"

	"csvstat/internal/cli"
)

func main() {
	os.Exit(cli.Run(os.Args[1:], os.Stdout, os.Stderr))
}
----CLI
package cli

import (
	"bytes"
	"encoding/csv"
	"errors"
	"fmt"
	"io"
	"os"

	"csvstat/internal/csvdata"
)

// Exit codes. Only cmd/csvstat calls os.Exit with the value Run returns.
const (
	exitOK          = 0
	exitOperational = 1
	exitUsage       = 2
	exitRejected    = 3
)

// usageLine shows both command forms on one line of standard error.
const usageLine = "usage: csvstat [--column <name>] <file> | csvstat --freq <name> [--top <n>] <file>"

// Run executes csvstat with args, which excludes the program name, and returns
// the process exit code. Stdout is written only on success; diagnostics go to
// stderr. Only cmd/csvstat calls os.Exit with this value.
func Run(args []string, stdout io.Writer, stderr io.Writer) int {
	opts, err := ParseArgs(args)
	if err != nil {
		fmt.Fprintf(stderr, "csvstat: %v; %s\n", err, usageLine)
		return exitUsage
	}

	f, err := os.Open(opts.File)
	if err != nil {
		fmt.Fprintf(stderr, "csvstat: %v\n", err)
		return exitOperational
	}
	defer f.Close()

	table, err := csvdata.Read(f)
	if err != nil {
		fmt.Fprintf(stderr, "csvstat: %s: %v\n", opts.File, err)
		return readFailureExit(err)
	}
	csvdata.Trim(table)
	if err := csvdata.Validate(table); err != nil {
		fmt.Fprintf(stderr, "csvstat: %s: %v\n", opts.File, err)
		return exitRejected
	}

	var rows [][]string
	switch {
	case opts.FreqSet:
		rows, err = freqRows(table, opts)
		if err != nil {
			fmt.Fprintf(stderr, "csvstat: %s: %v\n", opts.File, err)
			return exitRejected
		}
	case opts.ColumnSet:
		rows, err = columnRows(table, opts.Column)
		if err != nil {
			fmt.Fprintf(stderr, "csvstat: %s: %v\n", opts.File, err)
			return exitRejected
		}
	default:
		rows = profileRows(table)
	}
	return writeRows(stdout, stderr, rows)
}

// writeRows encodes rows as RFC 4180 CSV with \n line endings. The whole output is built in memory
// first, so stdout receives nothing unless encoding succeeds.
func writeRows(stdout io.Writer, stderr io.Writer, rows [][]string) int {
	var buf bytes.Buffer
	if err := csv.NewWriter(&buf).WriteAll(rows); err != nil {
		fmt.Fprintf(stderr, "csvstat: %v\n", err)
		return exitOperational
	}
	if _, err := stdout.Write(buf.Bytes()); err != nil {
		fmt.Fprintf(stderr, "csvstat: %v\n", err)
		return exitOperational
	}
	return exitOK
}

// readFailureExit maps a Read error to an exit code: a CSV syntax error is
// rejected input, while any other failure to read the file is operational.
func readFailureExit(err error) int {
	var parseErr *csv.ParseError
	if errors.As(err, &parseErr) {
		return exitRejected
	}
	return exitOperational
}
----ARGS
package cli

import (
	"errors"
	"flag"
	"fmt"
	"io"
	"strconv"
)

// Options is the parsed command line. ColumnSet, FreqSet and TopSet record
// whether the option was given, so an empty value is distinguishable from an
// absent option.
type Options struct {
	Column    string
	ColumnSet bool
	Freq      string
	FreqSet   bool
	Top       int
	TopSet    bool
	File      string
}

var errRepeated = errors.New("option given more than once")

// stringOption is a flag value that records presence and refuses repetition.
type stringOption struct {
	value *string
	set   *bool
}

func (o *stringOption) String() string {
	if o == nil || o.value == nil {
		return ""
	}
	return *o.value
}

func (o *stringOption) Set(v string) error {
	if *o.set {
		return errRepeated
	}
	*o.value = v
	*o.set = true
	return nil
}

// intOption is a flag value holding a decimal integer that refuses repetition.
type intOption struct {
	value *int
	set   *bool
}

func (o *intOption) String() string {
	if o == nil || o.value == nil {
		return ""
	}
	return strconv.Itoa(*o.value)
}

func (o *intOption) Set(v string) error {
	if *o.set {
		return errRepeated
	}
	n, err := strconv.Atoi(v)
	if err != nil {
		return fmt.Errorf("%q is not a decimal integer", v)
	}
	*o.value = n
	*o.set = true
	return nil
}

// ParseArgs parses options followed by exactly one file argument. Parsing stops
// at the first non-option argument, which must be the file, so any later
// argument, including an option, is an error.
func ParseArgs(args []string) (Options, error) {
	var opts Options
	fs := flag.NewFlagSet("csvstat", flag.ContinueOnError)
	fs.SetOutput(io.Discard)
	fs.Var(&stringOption{&opts.Column, &opts.ColumnSet}, "column", "")
	fs.Var(&stringOption{&opts.Freq, &opts.FreqSet}, "freq", "")
	fs.Var(&intOption{&opts.Top, &opts.TopSet}, "top", "")
	if err := fs.Parse(args); err != nil {
		return Options{}, err
	}

	rest := fs.Args()
	switch len(rest) {
	case 0:
		return Options{}, errors.New("missing file argument")
	case 1:
		opts.File = rest[0]
	default:
		return Options{}, fmt.Errorf("unexpected argument %q after file or extra file", rest[1])
	}
	if opts.ColumnSet && opts.FreqSet {
		return Options{}, errors.New("--column cannot be combined with --freq")
	}
	if opts.TopSet && !opts.FreqSet {
		return Options{}, errors.New("--top requires --freq")
	}
	if opts.TopSet && opts.Top <= 0 {
		return Options{}, fmt.Errorf("--top %d is not a positive integer", opts.Top)
	}
	return opts, nil
}

